<?php get_header(); ?><main class="main"><article class="article"><div class="container article__container"><?php if ( have_posts() ) : while ( have_posts() ) : the_post(); ?><header class="article__head"><p class="article__meta"><?php echo esc_html( get_the_date( 'j F Y' ) ); ?></p><h1 class="article__title"><?php the_title(); ?></h1><?php if ( has_post_thumbnail() ) : ?><div class="article__media"><?php the_post_thumbnail( 'large', array( 'class' => 'article__img' ) ); ?></div><?php endif; ?></header><div class="article__body"><?php the_content(); ?></div><a class="link-arrow" href="<?php echo esc_url( p313_page_url( 'blog' ) ); ?>">Все статьи <?php echo p313_icon( 'arrow' ); ?></a><?php endwhile; endif; ?></div></article></main><?php get_footer();
